    (5, 'PI Goals', 'PI bps (Base Business)', '50bps', 'N/A', '41bps', 'On track to bud', 'amber', 'CFO', ARRAY['CIM-15'], ARRAY['BRD-01'], 'BRD-01 1H2026 PI Program drives this. ~$1.77M in opportunities to capture.'),
    (6, 'M&A / VCP Goals', 'Acquired EBITDA', '$27.5M', 'N/A', '$23.0M', '$18.1M PY pace', 'amber', 'Head of M&A', ARRAY['CIM-04', 'CIM-05'], ARRAY['M&A-01', 'M&A-02', 'M&A-04'], 'YTD pace. M&A Engine + Tuck-In Machine driving.'),
