    (9, 'Customer Experience', 'Guest CSAT (company avg)', '≥4.65 (no brand <4.5)', 'populate', '—', '—', 'grey', 'VP Customer Experience', ARRAY[]::TEXT[], ARRAY['SVC-01', 'SVC-02'], 'Track ENPS too per cultural pillars. Service-First Talent + Tech-Enabled Service.')
